/* Browser checks: open index.html?test=1. Results appear in the console and window.PROTOTYPE_CHECKS. */
window.runPrototypeChecks=async function(){
 const results=[],sleep=()=>new Promise(r=>setTimeout(r,70));
 const assert=(ok,label)=>{if(!ok)throw new Error(label);results.push(label);};
 const screen=async id=>{location.hash=id;await sleep();assert(location.hash==='#'+id,'route '+id);};
 const click=async label=>{const el=[...document.querySelectorAll('[data-hotspot]')].find(e=>e.dataset.hotspot===label);if(!el)throw new Error('Missing hotspot '+label);el.click();await sleep();};
 const route=id=>assert(location.hash==='#'+id,'destination '+id);
 const dialogButton=async text=>{const el=[...document.querySelectorAll('dialog button')].find(e=>e.textContent===text);if(!el)throw new Error('Missing dialog action '+text);el.click();await sleep();};
 document.querySelector('#reset').click();await sleep();
 for(const [id,s]of Object.entries(window.PROTOTYPE_DATA.manifest.screens)){
  await screen(id);const img=document.querySelector('.screen-image');for(let t=0;!img.complete&&t<60;t++)await sleep();assert(img.naturalWidth===s.width&&img.naturalHeight===s.height,'image dimensions '+id);
  assert([...document.querySelectorAll('.hotspot')].every(b=>{const x=parseFloat(b.style.left),y=parseFloat(b.style.top);return x>=0&&y>=0&&x+parseFloat(b.style.width)<=s.width+.1&&y+parseFloat(b.style.height)<=s.height+.1;}),'hotspot bounds '+id);
 }
 await screen('aiuVt');await click('Buscar jitomate en el mercado');assert(document.querySelector('dialog').open,'search dialog opens');document.querySelector('#query').value='miel';document.querySelector('#search-form').requestSubmit();assert(document.querySelector('#search-error').textContent.includes('No hay resultados'),'unavailable search reports limitation');document.querySelector('#query').value='jitomate';document.querySelector('#search-form').requestSubmit();await sleep();route('GcHvf');
 await click('Ver lista');route('vHDrB');await click('Ver productos de El huerto de Pepe');assert(document.querySelector('dialog').textContent.includes('$28.00'),'Pepe price comparison');await dialogButton('Volver a comparar');await click('Ver productos de Doña Lucha');route('CTwi6');await click('Cerrar catálogo');route('vHDrB');
 await click('Ver cuadrícula');route('GcHvf');await click('Abrir carrito');assert(document.querySelector('dialog').textContent.includes('$77.00'),'desktop cart baseline');document.querySelector('dialog [data-q="0+"]').click();assert(document.querySelector('dialog [data-total]').textContent==='$109.00','desktop cart quantity recalculates');await dialogButton('Revisar apartado');route('QRWqF');assert(document.querySelector('.stage').textContent.includes('$109.00'),'review shows updated total');
 await click('Elegir horario de recogida');document.querySelector('#pickup').value='Hoy · 13:00–13:30';document.querySelector('dialog form').requestSubmit();await sleep();await click('Editar quién recoge');document.querySelector('#name').value='María';document.querySelector('dialog form').requestSubmit();await sleep();await click('Solicitar apartado');route('mLRAY');await click('Ver mi apartado');assert(document.querySelector('dialog').textContent.includes('María')&&document.querySelector('dialog').textContent.includes('13:00–13:30')&&document.querySelector('dialog').textContent.includes('$109.00'),'request preserves contact time and amount');document.querySelector('.close-dialog').click();await click('Volver al mercado');route('GcHvf');
 document.querySelector('#reset').click();await sleep();await screen('KKxdU');await click('Ver Mercado Medellín');route('p45ipV');await click('Ver lista');route('j6xDkI');await click('Ver productos de El huerto de Pepe');assert(document.querySelector('dialog').open,'mobile Pepe overlay');await dialogButton('Volver a comparar');await click('Ver productos de Doña Lucha');route('M2vgQT');await click('Aumentar jitomate');assert(document.querySelector('.stage').textContent.includes('$109.00'),'mobile catalogue quantity recalculates');await click('Cerrar catálogo');route('j6xDkI');await click('Abrir carrito');route('BVUFI');assert(document.querySelector('[data-total]').textContent==='$109.00','mobile cart retains quantity');document.querySelector('[data-review]').click();await sleep();route('a4Tzo');await click('Volver al catálogo');route('M2vgQT');await click('Revisar apartado');route('a4Tzo');await click('Solicitar apartado');route('EFCOW');await click('Ver mi apartado');assert(document.querySelector('dialog').textContent.includes('Por confirmar'),'mobile pending request');document.querySelector('.close-dialog').click();await click('Volver al mercado');route('j6xDkI');
 await screen('BVUFI');for(const i of [0,1,2]){document.querySelector(`[data-q="${i}0"]`).click();await sleep();}assert(document.querySelector('[data-review]').disabled,'empty cart cannot checkout');assert(document.querySelector('[data-total]').textContent==='$0.00','empty cart total');await screen('M2vgQT');await click('Revisar apartado');route('M2vgQT');assert(document.querySelector('#status').textContent.includes('al menos un producto'),'empty catalogue checkout blocked');
 await screen('T28VaZ');await click('Ir a productos');route('BnjUF');await click('Ir a pedidos');route('SWso9');await click('Aceptar pedido y preparar');route('OrB9k');await click('Marcar pedido como listo');assert(document.querySelector('#status').textContent.includes('listo'),'merchant ready feedback');await click('Ir a resumen');route('T28VaZ');await click('Ir a finanzas');route('bpqzW');await click('Guardar gasto de demostración');document.querySelector('#amount').value='0';document.querySelector('#concept').value='Insumos';assert(!document.querySelector('#amount').checkValidity(),'non-positive expense rejected');document.querySelector('#amount').value='25';document.querySelector('dialog form').requestSubmit();await sleep();assert(JSON.parse(sessionStorage.getItem('entrepuestos-prototype')).expenses[0].amount===25,'expense stored locally');await click('Ir a mi puesto');route('h91to');await click('Ver puesto público');route('CTwi6');
 await screen('T28VaZ');await click('Comparar precios del giro');route('D2zhK');await click('Revisar nuevo precio');route('Mgewd');await click('Editar nuevo precio');document.querySelector('#price').value='-1';assert(!document.querySelector('#price').checkValidity(),'negative price rejected');document.querySelector('#price').value='31.50';document.querySelector('dialog form').requestSubmit();await sleep();await click('Cancelar cambio de precio');route('D2zhK');assert(JSON.parse(sessionStorage.getItem('entrepuestos-prototype')).price===32,'cancel retains current price');await click('Revisar nuevo precio');await click('Editar nuevo precio');document.querySelector('#price').value='31.50';document.querySelector('dialog form').requestSubmit();await sleep();await click('Guardar nuevo precio');route('X0uXg');assert(document.querySelector('.stage').textContent.includes('$31.50'),'desktop saved price confirmation');await click('Volver al resumen');route('T28VaZ');assert(document.querySelector('.stage').textContent.includes('$31.50'),'dashboard reflects local price');
 await screen('pSIRS');await click('Comparar precios del giro');route('TtKVe');await click('Conservar precio actual');route('pSIRS');assert(JSON.parse(sessionStorage.getItem('entrepuestos-prototype')).price===31.5,'conserve preserves saved price');await click('Comparar precios del giro');await click('Revisar nuevo precio');route('y15ABx');await click('Guardar nuevo precio');route('kQgTm');assert(JSON.parse(sessionStorage.getItem('entrepuestos-prototype')).price===30,'mobile explicit save updates session price');await click('Volver al resumen');route('pSIRS');
 await screen('TtKVe');document.querySelector('#references-scenario').click();await sleep();await click('Revisar nuevo precio');route('TtKVe');assert(document.querySelector('.live-panel').textContent.includes('No hay referencias'),'missing references blocks proposal');document.querySelector('#references-scenario').click();await sleep();await click('Revisar nuevo precio');route('y15ABx');document.querySelector('#failure-scenario').checked=true;document.querySelector('#failure-scenario').dispatchEvent(new Event('change'));await click('Editar nuevo precio');document.querySelector('#price').value='35';document.querySelector('dialog form').requestSubmit();await sleep();await click('Guardar nuevo precio');assert(document.querySelector('dialog').textContent.includes('Tu precio anterior sigue vigente'),'save failure keeps current price');assert(JSON.parse(sessionStorage.getItem('entrepuestos-prototype')).price===30,'failed save does not apply draft');await dialogButton('Reintentar');route('kQgTm');assert(JSON.parse(sessionStorage.getItem('entrepuestos-prototype')).price===35,'retry applies preserved proposal');
 await screen('defJ5');await click('Ver productos favoritos');route('M2vgQT');await screen('unknown');assert(document.querySelector('h1').textContent==='Pantalla no encontrada','unknown route recovery');document.querySelector('#reset').click();await sleep();assert(document.querySelectorAll('.journey').length===5,'reset returns to five journeys');
 window.PROTOTYPE_CHECKS={passed:results.length,results};console.log('PROTOTYPE CHECKS',window.PROTOTYPE_CHECKS);return window.PROTOTYPE_CHECKS;
};
if(new URLSearchParams(location.search).has('test'))window.runPrototypeChecks().catch(error=>{window.PROTOTYPE_CHECKS={error:error.message};console.error(error);});
